    goldilocks: true,
    goldilocks_range: { green_min: 4, green_max: 6, yellow_low: 3, yellow_high: 8 }
  },
  {
    id: "msa_10",
    metric: "Cap Rate Spread",
    category: "Valuation",
    threshold: ">200 bps above 10-year Treasury",
    description: "Adequate risk premium over risk-free rate",
    data_sources: ["CBRE Cap Rate Survey"]
