  {
    id: "sub_5",
    metric: "Transport Access (Positive)",
    category: "Connectivity",
    threshold: "Highway/Transit 1-2 miles (GOLDILOCKS: <0.5mi = RED noise, >3mi = YELLOW inconvenient)",
    description: "Easy commute without highway noise",
    goldilocks: true,
    goldilocks_range: { green_min: 1, green_max: 2, red_close: 0.5, yellow_far: 3 }
  },
  {
    id: "sub_6",
    metric: "Transport Avoidance (Negative)",
    category: "Risk Assessment",
    threshold: "NOT adjacent to highway/airport/rail yard (<0.5mi = RED)",
    description: "Avoid noise and air quality issues",
    data_sources: ["Noise Maps", "FAA Data"]
  },
  {
    id: "sub_7",
    metric: "Path of Growth",
    category: "Appreciation",
    threshold: "On development corridor OR gentrifying area",
    description: "Future value creation from area improvement",
    data_sources: ["City Development Plans"]
  },
  {
    id: "sub_8",
    metric: "Zoning Protections",
    category: "Legal/Regulatory",
    threshold: "Residential-only OR MF-designated zoning",
    description: "Prevents industrial encroachment",
    data_sources: ["City Zoning Maps"]
  },
  {
    id: "sub_9",
    metric: "Renter Density",
    category: "Demographics",
    threshold: ">50% renters (Context: Urban >70% OK, Suburban >70% = YELLOW distress signal)",
    description: "Strong renter culture",
    context_aware: true,
    data_sources: ["Census ACS"]
  },
  {
    id: "sub_10",
    metric: "Proximity to MF Assets",
    category: "Competition/Validation",
    threshold: "3+ comparable MF properties <1 mile",
    description: "Clustering validates submarket",
    data_sources: ["CoStar", "Apartment List"]
  },
  {
    id: "sub_11",
    metric: "Cluster Growth Potential",
    category: "Appreciation",
    threshold: "Land available for additional MF development",
    description: "Room to grow = future exit liquidity",
    data_sources: ["Zoning Maps", "Vacant Land Records"]
  },
  {
    id: "sub_12",
    metric: "Taxes and Fees",
    category: "Operating Costs",
    threshold: "<2% of property value annually",
    description: "Low tax burden improves cash flow",
    override_priority: "HIGH - User tax abatement docs take precedence",
    data_sources: ["County Tax Assessor"]
  },
  {
    id: "sub_13",
    metric: "Historical Appreciation",
    category: "Returns",
    threshold: ">3% annually (5-year trailing)",
    description: "Property values rising faster than inflation",
    data_sources: ["Zillow", "CoStar"]
  },
  {
    id: "sub_14",
    metric: "Government Volatility",
    category: "Risk Assessment",
    threshold: "Stable governance, no radical policy shifts",
    description: "Predictable regulatory environment",
    data_sources: ["Municipal Records"]
  }
];

// -----------------------------------------------------------------------------
// Extract research data from Perplexity
// -----------------------------------------------------------------------------
const researchNode = $('Perplexity Research').first();
let researchData = 'Research data not available';
try {
  const content = researchNode.json?.choices?.[0]?.message?.content;
  if (content) {
    researchData = content;
  }
} catch (e) {
  console.error('Failed to extract Perplexity data:', e.message);
}

// -----------------------------------------------------------------------------
// Extract context documents
// -----------------------------------------------------------------------------
const contextNode = $('Parse Context Docs').first();
const contextDocs = contextNode.json?.context_text || 'No context documents uploaded';

// -----------------------------------------------------------------------------
// Extract address and deal name
// -----------------------------------------------------------------------------
const inputNode = $('Extract Input Data').first();
const address = inputNode.json?.address || 'Address not provided';
const dealName = inputNode.json?.deal_name || 'Unnamed Deal';

// -----------------------------------------------------------------------------
// Format criteria for Gemini prompt
// -----------------------------------------------------------------------------
const formatCriteria = (criteria) => {
  return criteria.map(c => {
    let line = `${c.id}: ${c.metric} | Threshold: ${c.threshold}`;
    if (c.goldilocks) {
      line += ' [GOLDILOCKS LOGIC APPLIES]';
    }
    if (c.context_aware) {
      line += ' [CONTEXT-AWARE: Urban vs Suburban]';
    }
    if (c.override_priority) {
      line += ` [OVERRIDE: ${c.override_priority}]`;
    }
    return line;
  }).join('\n');
};

return {
  msa_criteria: formatCriteria(MSA_CRITERIA),
  submarket_criteria: formatCriteria(SUBMARKET_CRITERIA),
  msa_criteria_json: JSON.stringify(MSA_CRITERIA),
  submarket_criteria_json: JSON.stringify(SUBMARKET_CRITERIA),
  research_data: researchData,
  context_docs: contextDocs,
  address: address,
  deal_name: dealName
