// Extract and validate the 30-point heat map JSON from Gemini response
const geminiResponse = $input.first().json;

// Extract content from Gemini response structure
let responseText;
try {
  responseText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!responseText) {
    throw new Error('No text content in Gemini response');
  }
} catch (e) {
  throw new Error(`Failed to extract Gemini response: ${e.message}. Response: ${JSON.stringify(geminiResponse).slice(0, 500)}`);
}

// Parse JSON from response
let heatMapJson;
try {
  // Try direct parse first
  heatMapJson = JSON.parse(responseText);
} catch (e) {
  // Try to extract JSON array from markdown code blocks
  const jsonMatch = responseText.match(/\[\s*\{[\s\S]*\}\s*\]/); 
  if (jsonMatch) {
    heatMapJson = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error(`Failed to parse JSON: ${e.message}. Content: ${responseText.slice(0, 500)}`);
  }
}

// Validation
if (!Array.isArray(heatMapJson)) {
  throw new Error('Heat map must be an array');
}

if (heatMapJson.length !== 30) {
  throw new Error(`Heat map must contain exactly 30 items, got ${heatMapJson.length}`);
}

// Validate required fields and status values
const requiredFields = ['id', 'metric', 'threshold', 'value', 'status', 'reasoning', 'source'];
const validStatuses = ['GREEN', 'YELLOW', 'RED'];

for (let i = 0; i < heatMapJson.length; i++) {
  const item = heatMapJson[i];

  for (const field of requiredFields) {
    if (!(field in item)) {
      throw new Error(`Item ${i} (${item.id || 'unknown'}) missing required field: ${field}`);
    }
  }

  if (!validStatuses.includes(item.status)) {
    throw new Error(`Item ${i} (${item.id}) has invalid status: ${item.status}. Must be GREEN, YELLOW, or RED`);
  }

  if (item.reasoning.length < 20) {
    console.warn(`Item ${i} (${item.id}) has short reasoning: ${item.reasoning.length} chars`);
  }
}

// Calculate summary stats
const greenCount = heatMapJson.filter(i => i.status === 'GREEN').length;
const yellowCount = heatMapJson.filter(i => i.status === 'YELLOW').length;
const redCount = heatMapJson.filter(i => i.status === 'RED').length;

// Determine recommendation
let recommendation;
if (redCount > 5) {
  recommendation = 'NO-GO';
} else if (redCount >= 3) {
  recommendation = 'CAUTION';
} else {
  recommendation = 'PROCEED';
}

return {
  heat_map: heatMapJson,
  validation_passed: true,
  total_items: heatMapJson.length,
  green_count: greenCount,
  yellow_count: yellowCount,
  red_count: redCount,
  recommendation: recommendation,
  address: $('Extract Input Data').first().json.address,
  deal_name: $('Extract Input Data').first().json.deal_name
};

// Build Heat Map HTML Report for PDF generation
const data = $input.first().json;
const heatMap = data.heat_map;
const dealName = data.deal_name;
const address = data.address;
const recommendation = data.recommendation;
const greenCount = data.green_count;
const yellowCount = data.yellow_count;
const redCount = data.red_count;

// Status color mapping
const statusColors = {
  'GREEN': '#22c55e',
  'YELLOW': '#eab308',
  'RED': '#ef4444'
};

const statusBgColors = {
  'GREEN': '#dcfce7',
  'YELLOW': '#fef9c3',
  'RED': '#fee2e2'
};

// Recommendation styling
const recColors = {
  'PROCEED': { bg: '#dcfce7', text: '#166534', label: '✓ PROCEED' },
  'CAUTION': { bg: '#fef9c3', text: '#854d0e', label: '⚠ CAUTION' },
  'NO-GO': { bg: '#fee2e2', text: '#991b1b', label: '✗ NO-GO' }
};
const rec = recColors[recommendation] || recColors['CAUTION'];

// Split criteria
const msaCriteria = heatMap.filter(c => c.id.startsWith('msa_'));
const subCriteria = heatMap.filter(c => c.id.startsWith('sub_'));

// Build criteria rows
const buildRow = (item) => `
  <tr style="border-bottom: 1px solid #e5e7eb;">
    <td style="padding: 12px 8px; font-weight: 500;">${item.id}</td>
    <td style="padding: 12px 8px;">${item.metric}</td>
    <td style="padding: 12px 8px; color: #6b7280;">${item.threshold}</td>
    <td style="padding: 12px 8px;">${item.value}</td>
    <td style="padding: 12px 8px;">
      <span style="display: inline-block; padding: 4px 12px; border-radius: 9999px; font-size: 12px; font-weight: 600; background: ${statusBgColors[item.status]}; color: ${statusColors[item.status]};">
        ${item.status}
      </span>
    </td>
    <td style="padding: 12px 8px; font-size: 13px; color: #4b5563; max-width: 300px;">${item.reasoning}</td>
  </tr>
`;

const html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1f2937; line-height: 1.5; padding: 40px; }
    .header { text-align: center; margin-bottom: 40px; padding-bottom: 20px; border-bottom: 2px solid #e5e7eb; }
    .header h1 { font-size: 28px; color: #111827; margin-bottom: 8px; }
