    .summary-card { padding: 20px 30px; border-radius: 12px; text-align: center; }
    .summary-card .number { font-size: 36px; font-weight: 700; }
    .summary-card .label { font-size: 14px; color: #6b7280; margin-top: 4px; }
    .recommendation { text-align: center; margin: 30px 0; padding: 20px; border-radius: 12px; }
    .recommendation .label { font-size: 24px; font-weight: 700; }
    .section { margin: 40px 0; }
    .section h2 { font-size: 20px; color: #374151; margin-bottom: 16px; padding-bottom: 8px; border-bottom: 2px solid #e5e7eb; }
    table { width: 100%; border-collapse: collapse; font-size: 14px; }
    th { text-align: left; padding: 12px 8px; background: #f9fafb; font-weight: 600; color: #374151; border-bottom: 2px solid #e5e7eb; }
    .footer { margin-top: 40px; padding-top: 20px; border-top: 2px solid #e5e7eb; text-align: center; color: #9ca3af; font-size: 12px; }
  </style>
</head>
<body>
  <div class="header">
    <h1>🏢 ${dealName}</h1>
    <p>${address}</p>
    <p style="margin-top: 8px; font-size: 12px;">Generated: ${new Date().toISOString().split('T')[0]}</p>
  </div>

  <div class="summary">
    <div class="summary-card" style="background: #dcfce7;">
      <div class="number" style="color: #166534;">${greenCount}</div>
      <div class="label">GREEN</div>
    </div>
    <div class="summary-card" style="background: #fef9c3;">
      <div class="number" style="color: #854d0e;">${yellowCount}</div>
      <div class="label">YELLOW</div>
    </div>
    <div class="summary-card" style="background: #fee2e2;">
      <div class="number" style="color: #991b1b;">${redCount}</div>
      <div class="label">RED</div>
    </div>
  </div>

  <div class="recommendation" style="background: ${rec.bg};">
    <div class="label" style="color: ${rec.text};">${rec.label}</div>
    <p style="color: ${rec.text}; margin-top: 8px;">
      ${recommendation === 'PROCEED' ? 'Proceed to full due diligence' : recommendation === 'CAUTION' ? 'Investment Committee review required' : 'Deal does not meet investment criteria'}
    </p>
  </div>

  <div class="section">
    <h2>📊 MSA Criteria (${msaCriteria.length} points)</h2>
    <table>
      <thead>
        <tr>
          <th>ID</th>
          <th>Metric</th>
          <th>Threshold</th>
          <th>Value</th>
          <th>Status</th>
          <th>Reasoning</th>
        </tr>
      </thead>
      <tbody>
        ${msaCriteria.map(buildRow).join('')}
      </tbody>
    </table>
  </div>

  <div class="section">
    <h2>📍 Sub-Market Criteria (${subCriteria.length} points)</h2>
    <table>
      <thead>
        <tr>
          <th>ID</th>
          <th>Metric</th>
          <th>Threshold</th>
          <th>Value</th>
          <th>Status</th>
          <th>Reasoning</th>
        </tr>
      </thead>
      <tbody>
        ${subCriteria.map(buildRow).join('')}
      </tbody>
    </table>
  </div>

  <div class="footer">
    <p>AI Multifamily Deep Research Engine | 30-Point Heat Map Analysis</p>
    <p>This report was generated automatically. Always verify data with primary sources.</p>
  </div>
</body>
</html>
`;

return {
  html: html,
  deal_name: dealName,
  address: address,
  recommendation: recommendation,
  heat_map: heatMap,
  green_count: greenCount,
  yellow_count: yellowCount,
  red_count: redCount
};
